      const app = document.getElementById("app");

      function el(tag, attrs, ...children) {
        const node = document.createElement(tag);
        if (attrs) {
          for (const [key, value] of Object.entries(attrs)) {
            if (value === null || value === undefined || value === false) continue;
            if (key === "className") {
              node.className = value;
            } else if (key === "textContent") {
              node.textContent = value;
            } else if (key.startsWith("on") && typeof value === "function") {
              node.addEventListener(key.slice(2).toLowerCase(), value);
            } else {
              node.setAttribute(key, value);
            }
          }
        }
        for (const child of children.flat()) {
          if (child === null || child === undefined || child === false) continue;
          node.appendChild(child.nodeType ? child : document.createTextNode(child));
        }
        return node;
      }

      function createField({ id, label, type, autocomplete, required, helperText, placeholder, validate }) {
        const field = el("div", { className: "form-field" });
        const input = el("input", {
          id,
          name: id,
          type,
          autocomplete,
          placeholder,
          ...(required ? { required: "required" } : {}),
        });
        const errorId = `${id}-error`;
        const helpId = helperText ? `${id}-help` : null;
        const error = el("p", {
          id: errorId,
          className: "error",
          "aria-live": "polite",
        });

        const labelNode = el(
          "label",
          { for: id },
          label,
          required ? el("span", { className: "required", "aria-hidden": "true", textContent: " *" }) : ""
        );

        const helpNode = helperText
          ? el("p", { id: helpId, className: "helper", textContent: helperText })
          : null;

        const syncA11y = () => {
          const ids = [];
          if (helpId) ids.push(helpId);
          if (error.textContent) ids.push(errorId);
          if (ids.length) {
            input.setAttribute("aria-describedby", ids.join(" "));
          } else {
            input.removeAttribute("aria-describedby");
          }
          if (error.textContent) {
            input.setAttribute("aria-invalid", "true");
          } else {
            input.removeAttribute("aria-invalid");
          }
        };

        const setError = (message) => {
          error.textContent = message || "";
          syncA11y();
        };

        const validateField = () => {
          const value = input.value.trim();
          const message = validate(value);
          setError(message);
          return !message;
        };

        input.addEventListener("blur", validateField);
        input.addEventListener("input", () => {
          if (error.textContent) {
            validateField();
          } else if (input.value.trim()) {
            syncA11y();
          }
        });

        field.append(
          labelNode,
          input,
          helpNode || document.createTextNode(""),
          error
        );

        syncA11y();

        return { field, input, validateField, setError };
      }

