        const form = el("form", { novalidate: "novalidate" });
        const status = el("p", {
          id: "form-status",
          className: "visually-hidden",
          "aria-live": "polite",
        });

        const fullName = createField({
          id: "full-name",
          label: "Full name",
          type: "text",
          autocomplete: "name",
          required: true,
          placeholder: "Ada Lovelace",
          validate(value) {
            if (!value) return "Error: Full name is required.";
            return "";
          },
        });

        const email = createField({
          id: "email-address",
          label: "Email address",
          type: "email",
          autocomplete: "email",
          required: true,
          placeholder: "name@example.com",
          validate(value) {
            if (!value) return "Error: Email address is required.";
            if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)) {
              return "Error: Enter a valid email address, like name@example.com.";
            }
            return "";
          },
        });

        const phone = createField({
          id: "phone-number",
          label: "Phone number",
          type: "tel",
          autocomplete: "tel",
          required: false,
          placeholder: "+1 (555) 123-4567",
          helperText: "Optional. Use digits with spaces, dashes, or parentheses. Example: +1 (555) 123-4567.",
          validate(value) {
            if (!value) return "";
            const digits = value.replace(/\D/g, "");
            const allowed = /^[0-9()+\-\s.]+$/.test(value);
            if (!allowed || digits.length < 10 || digits.length > 15) {
              return "Error: Enter a valid phone number, like +1 (555) 123-4567.";
            }
            return "";
          },
        });

        const submit = el("button", { type: "submit", textContent: "Send message" });
        const fineprint = el("p", {
          className: "fineprint",
          textContent: "Fields marked with an asterisk are required.",
        });

        form.append(fullName.field, email.field, phone.field, el("div", { className: "actions" }, submit), fineprint, status);

        form.addEventListener("submit", (event) => {
          event.preventDefault();
          const validators = [fullName, email, phone];
          const invalid = validators.filter((item) => !item.validateField());

          if (invalid.length) {
            invalid[0].input.focus();
            return;
          }

          status.textContent = "All fields look good.";
        });

        return form;
      }

      function App() {
        const main = el("main", { id: "main" });
        const shell = el("div", { className: "page-shell" });
        const hero = el(
          "header",
          { className: "hero" },
          el("p", { className: "eyebrow", textContent: "Support page" }),
          el("h1", { textContent: "Contact support" }),
          el(
            "p",
            {
              className: "lede",
              textContent: "Send us your details and we will follow up by email. The form validates required fields inline and highlights any formatting issues before you send it.",
            }
          )
        );
        const card = el("section", { className: "card", "aria-labelledby": "contact-heading" });
        card.appendChild(el("h2", { id: "contact-heading", className: "visually-hidden", textContent: "Contact form" }));
        card.appendChild(SupportForm());
        shell.append(hero, card);
        main.appendChild(shell);
        return main;
      }

      app.appendChild(App());
    </script>
